"""
This module provides aggregated private data and utilities functions about the
available backends.

WARNING: The *pathspec._backends* package is not part of the public API. Its
contents and structure are likely to change.
"""

from collections.abc import (
	Sequence)
from typing import (
	cast)

from pathspec.backend import (
	BackendNamesHint,
	_Backend)
from pathspec.pattern import (
	Pattern,
	RegexPattern)

from ._utils import (
	has_unsupported_flags)

from .hyperscan.base import (
	hyperscan_error)
from .hyperscan.gitignore import (
	HyperscanGiBackend)
from .hyperscan.pathspec import (
	HyperscanPsBackend)
from .re2.base import (
	re2_error)
from .re2.gitignore import (
	Re2GiBackend)
from .re2.pathspec import (
	Re2PsBackend)
from .simple.gitignore import (
	SimpleGiBackend)
from .simple.pathspec import (
	SimplePsBackend)

_BEST_BACKEND: BackendNamesHint
"""
The best available backend.
"""

if re2_error is None:
	_BEST_BACKEND = 're2'
elif hyperscan_error is None:
	_BEST_BACKEND = 'hyperscan'
else:
	_BEST_BACKEND = 'simple'


def make_gitignore_backend(
	name: BackendNamesHint,
	patterns: Sequence[Pattern],
) -> _Backend:
	"""
	Create the specified backend with the supplied patterns for
	:class:`~pathspec.gitignore.GitIgnoreSpec`.

	*name* (:class:`str`) is the name of the backend.

	*patterns* (:class:`.Iterable` of :class:`.Pattern`) contains the compiled
	patterns.

	Returns the backend (:class:`._Backend`).
	"""
	if name == 'best':
		name = _BEST_BACKEND
		if name != 'simple' and has_unsupported_flags(patterns):
			# Only the simple backend can keep the compile flags of the patterns it
			# was given.
			name = 'simple'

	if name == 'hyperscan':
		return HyperscanGiBackend(cast(Sequence[RegexPattern], patterns))
	elif name == 're2':
		return Re2GiBackend(cast(Sequence[RegexPattern], patterns))
	elif name == 'simple':
		return SimpleGiBackend(cast(Sequence[RegexPattern], patterns))
	else:
		raise ValueError(f"Backend {name=!r} is invalid.")


def make_pathspec_backend(
	name: BackendNamesHint,
	patterns: Sequence[Pattern],
) -> _Backend:
	"""
	Create the specified backend with the supplied patterns for
	:class:`~pathspec.pathspec.PathSpec`.

	*name* (:class:`str`) is the name of the backend.

	*patterns* (:class:`Iterable` of :class:`Pattern`) contains the compiled
	patterns.

	Returns the backend (:class:`._Backend`).
	"""
	if name == 'best':
		name = _BEST_BACKEND
		if name != 'simple' and has_unsupported_flags(patterns):
			# Only the simple backend can keep the compile flags of the patterns it
			# was given.
			name = 'simple'

	if name == 'hyperscan':
		return HyperscanPsBackend(cast(Sequence[RegexPattern], patterns))
	elif name == 're2':
		return Re2PsBackend(cast(Sequence[RegexPattern], patterns))
	elif name == 'simple':
		return SimplePsBackend(patterns)
	else:
		raise ValueError(f"Backend {name=!r} is invalid.")

"""
This module provides the simple backend for :class:`~pathspec.gitignore.GitIgnoreSpec`.

WARNING: The *pathspec._backends.simple* package is not part of the public API.
Its contents and structure are likely to change.
"""

from collections.abc import (
	Sequence)
from typing import (
	Optional)  # Replaced by `X | None` in 3.10.

from pathspec.pattern import (
	RegexPattern)
from pathspec.patterns.gitignore.spec import (
	_DIR_MARK)
from pathspec._typing import (
	override)  # Added in 3.12.

from .pathspec import (
	SimplePsBackend)


class SimpleGiBackend(SimplePsBackend):
	"""
	The :class:`SimpleGiBackend` class is the default (or simple) implementation
	used by :class:`~pathspec.gitignore.GitIgnoreSpec` for matching files.
	"""

	# Change type hint.
	_patterns: list[tuple[int, RegexPattern]]  # type: ignore[assignment]

	def __init__(
		self,
		patterns: Sequence[RegexPattern],
		*,
		no_filter: Optional[bool] = None,
		no_reverse: Optional[bool] = None,
	) -> None:
		"""
		Initialize the :class:`SimpleGiBackend` instance.

		*patterns* (:class:`Sequence` of :class:`.RegexPattern`) contains the
		compiled patterns.

		*no_filter* (:class:`bool`) is whether to keep no-op patterns (:data:`True`),
		or remove them (:data:`False`).

		*no_reverse* (:class:`bool`) is whether to keep the pattern order
		(:data:`True`), or reverse the order (:data:`True`).
		"""
		super().__init__(patterns, no_filter=no_filter, no_reverse=no_reverse)

	@override
	def match_file(self, file: str) -> tuple[Optional[bool], Optional[int]]:
		"""
		Check the file against the patterns.

		*file* (:class:`str`) is the normalized file path to check.

		Returns a :class:`tuple` containing whether to include *file* (:class:`bool`
		or :data:`None`), and the index of the last matched pattern (:class:`int` or
		:data:`None`).
		"""
		return self._match(file, check_ancestors=True)

	def _match(
		self, file: str, check_ancestors: bool,
	) -> tuple[Optional[bool], Optional[int]]:
		"""
		Implements :meth:`match_file`. *check_ancestors* (:class:`bool`) is
		whether to ask if an ancestor directory of *file* is excluded; see
		:meth:`_ancestor_excluded` for why it can be skipped.
		"""
		is_reversed = self._is_reversed

		# Resolve the ancestor directory and the file separately: a file negation
		# only applies while no ancestor directory is excluded.
		dir_include: Optional[bool] = None
		dir_index: Optional[int] = None
		file_include: Optional[bool] = None
		file_index: Optional[int] = None

		for index, pattern in self._patterns:
			if (
				(include := pattern.include) is not None
				and (match := pattern.match_file(file)) is not None
			):
				# Pattern matched.
				if match.match.groupdict().get(_DIR_MARK):
					# A pattern can match both a strict ancestor of the file and the
					# file itself. For anchored patterns there is only one match, but
					# `**/` compiles to the unanchored `(?P<ps_d>/)`: on "a/b/" it
					# matches at "a/" and at "b/", and `match` only returns the first.
					is_ancestor = is_self = False
					assert pattern.regex is not None, pattern
					for dir_match in pattern.regex.finditer(file):
						if dir_match.end(_DIR_MARK) < len(file):
							is_ancestor = True
						else:
							is_self = True

					if is_ancestor and (dir_include is None or not is_reversed):
						dir_include = include
						dir_index = index

					if is_self and (file_include is None or not is_reversed):
						file_include = include
						file_index = index
				elif file_include is None or not is_reversed:
					# Pattern matched by a file pattern.
					file_include = include
					file_index = index

		if dir_include and check_ancestors and self._ancestor_excluded(file):
			return (dir_include, dir_index)
		elif file_include is not None:
			return (file_include, file_index)
		elif dir_include:
			# An ancestor matched an exclude pattern, but the spec as a whole
			# re-includes that ancestor, so the rule does not apply.
			return (None, None)
		else:
			return (dir_include, dir_index)

	def _ancestor_excluded(self, file: str) -> bool:
		"""
		Whether any strict ancestor directory of *file* is excluded. Git stops
		descending at the first excluded directory, so the ancestors are asked
		outermost first, each as a directory query (trailing slash included).
		By the time an ancestor is asked, every ancestor above it is known not to
		be excluded, so it is matched without checking its own ancestors again;
		otherwise each level re-asks all the levels above it and the work grows
		exponentially with depth.
		"""
		index = file.find('/')
		while index != -1 and index + 1 < len(file):
			ancestor_include, _ancestor_index = self._match(
				file[:index + 1], check_ancestors=False,
			)
			if ancestor_include:
				return True
			index = file.find('/', index + 1)

		return False

"""
This module provides stubs for type hints not supported by all relevant Python
versions.

NOTICE: This project should have zero required dependencies, which means it
cannot simply require :module:`typing_extensions`, and I do not want to maintain
a vendored copy of :module:`typing_extensions`.
"""

import functools
import sys
import warnings
from typing import (
	Any,
	Callable,  # Replaced by `collections.abc.Callable` in 3.9.2.
	Optional,  # Replaced by `X | None` in 3.10.
	TypeVar)

F = TypeVar('F', bound=Callable[..., Any])

# AnyStr is deprecated since 3.13, and will be removed in 3.18.
if sys.version_info >= (3, 18):
	AnyStr = TypeVar('AnyStr', str, bytes)
else:
	from typing import AnyStr

# Never was added in 3.11.
if sys.version_info >= (3, 11):
	from typing import Never
else:
	from typing import NoReturn as Never

# deprecated was added in 3.13.
if sys.version_info >= (3, 13):
	from warnings import deprecated
else:
	try:
		from typing_extensions import deprecated
	except ImportError:
		def deprecated(
			message: str,
			/, *,
			category: Optional[type[Warning]] = DeprecationWarning,
			stacklevel: int = 1,
		) -> Callable[[F], F]:
			def decorator(f: F) -> F:
				@functools.wraps(f)
				def wrapper(*a, **k):
					warnings.warn(message, category=category, stacklevel=stacklevel+1)
					return f(*a, **k)
				return wrapper
			return decorator

# override was added in 3.12.
if sys.version_info >= (3, 12):
	from typing import override
else:
	try:
		from typing_extensions import override
	except ImportError:
		def override(f: F, /) -> F:
			return f


def assert_unreachable(message: str) -> Never:
	"""
	The code path is unreachable. Raises an :class:`AssertionError`.

	*message* (:class:`str`) is the error message.
	"""
	raise AssertionError(message)

"""
.. version-deprecated: 1.0.0
	This module is superseded by :module:`pathspec.patterns.gitignore`.
"""

from pathspec import util
from pathspec._typing import (
	deprecated,  # Added in 3.13.
	override)  # Added in 3.12.

from .gitignore.spec import (
	GitIgnoreSpecPattern)

# DEPRECATED: Deprecated since version 1.0.0. Expose GitWildMatchPatternError
# in this module for backward compatibility.
from .gitignore import (
	GitIgnorePatternError as GitWildMatchPatternError)


class GitWildMatchPattern(GitIgnoreSpecPattern):
	"""
	.. version-deprecated:: 1.0.0
		This class is superseded by :class:`GitIgnoreSpecPattern` and
		:class:`~pathspec.patterns.gitignore.basic.GitIgnoreBasicPattern`.
	"""

	@deprecated((
		"GitWildMatchPattern ('gitwildmatch') is deprecated. Use 'gitignore' for "
		"GitIgnoreBasicPattern or GitIgnoreSpecPattern instead."
	))
	def __init__(self, *args, **kw) -> None:
		"""
		Warn about deprecation.
		"""
		super().__init__(*args, **kw)

	@override
	@classmethod
	@deprecated((
		"GitWildMatchPattern ('gitwildmatch') is deprecated. Use 'gitignore' for "
		"GitIgnoreBasicPattern or GitIgnoreSpecPattern instead."
	))
	def pattern_to_regex(cls, *args, **kw):
		"""
		Warn about deprecation.
		"""
		return super().pattern_to_regex(*args, **kw)


# DEPRECATED: Deprecated since version 1.0.0. Register GitWildMatchPattern as
# "gitwildmatch" for backward compatibility.
util.register_pattern('gitwildmatch', GitWildMatchPattern)
